add_filter( 'woocommerce_hpos_admin_search_filters', 'perfectpixel_order_search_country_option' );
add_filter( 'woocommerce_hpos_generate_where_for_search_filter', 'perfectpixel_order_search_country_where', 10, 4 );

function perfectpixel_order_search_country_option( $options ) {
	$options['perfectpixel_country'] = 'Χώρα (κωδικός 2 γραμμάτων)';
	return $options;
}

function perfectpixel_order_search_country_where( $where, $search_term, $search_filter, $query ) {
	global $wpdb;
	if ( 'perfectpixel_country' !== $search_filter ) {
		return $where;
	}
	$code = strtoupper( substr( preg_replace( '/[^A-Za-z]/', '', (string) $search_term ), 0, 2 ) );
	if ( 2 !== strlen( $code ) ) {
		return '1=0';
	}
	$orders    = $query->get_table_name( 'orders' );
	$addresses = $query->get_table_name( 'addresses' );
	return $wpdb->prepare( "{$orders}.id IN ( SELECT order_id FROM {$addresses} WHERE country = %s )", $code );
}
